                print(f"IP change detected: {previous_ip} -> {current_ips}")

            # Update the previous IP to the current one
            previous_ip = current_ips

            # Resolve PTR records for each IP to find associated domains
            for ip in current_ips:
                try:
                    ptr_records = dns.resolver.resolve(ip, 'PTR')
                    for rdata in ptr_records:
                        associated_domains.add(rdata.target.to_text())
                except Exception as e:
                    print(f"Failed to resolve PTR record for {ip}: {e}")

            # Print associated domains
            if associated_domains:
                print(f"Associated domains: {', '.join(associated_domains)}")

        except Exception as e:
            print(f"Error resolving domain {domain}: {e}")

        # Wait for the specified interval before checking again
        time.sleep(interval)

if __name__ == "__main__":
