#!/usr/bin/env python3

import os
import subprocess

def check_privileges():
    # Check if the script is running with root privileges
    if os.geteuid() != 0:
        print("This script requires root privileges. Please run as root.")
        exit(1)

def enumerate_sudoers():
    # Enumerate users allowed to use sudo
    try:
        output = subprocess.check_output(['getent', 'sudoers']).decode()
        print("Sudoers configuration:")
        print(output)
    except Exception as e:
        print(f"Error enumerating sudoers: {e}")

def check_suid_binaries():
    # Find SUID binaries
    suid_binaries = []
    try:
        for root, dirs, files in os.walk('/'):
            for file in files:
                full_path = os.path.join(root, file)
                if os.path.isfile(full_path) and oct(os.stat(full_path).st_mode)[-3:] == '4755':
                    suid_binaries.append(full_path)
        print(f"SUID binaries found: {len(suid_binaries)}")
        for binary in suid_binaries:
            print(binary)
    except Exception as e:
        print(f"Error checking SUID binaries: {e}")

def check_world_writable_dirs():
    # Find world-writable directories
    ww_dirs = []
    try:
        for root, dirs, files in os.walk('/'):
            for dir in dirs:
                full_path = os.path.join(root, dir)
                if oct(os.stat(full_path).st_mode)[-3:] == '777':
                    ww_dirs.append(full_path)
        print(f"World-writable directories found: {len(ww_dirs)}")
        for directory in ww_dirs:
            print(directory)
    except Exception as e:
        print(f"Error checking world-writable directories: {e}")

def check_cron_jobs():
    # Check system-wide and user-specific cron jobs
    try:
        print("System-wide cron jobs:")
        subprocess.run(['crontab', '-l'], check=True)
        for user in [user.split(':')[0] for user in open('/etc/passwd').readlines() if int(user.split(':')[2]) == 0]:
            print(f"\nCron jobs for {user}:")
            subprocess.run(['sudo', '-u', user, 'crontab', '-l'], check=True)
    except Exception as e:
        print(f"Error checking cron jobs: {e}")

def main():
    check_privileges()
    enumerate_sudoers()
    check_suid_binaries()
    check_world_writable_dirs()
    check_cron_jobs()

if __name__ == "__main__":
    main()
